export function validate(model, value) {
  const spec = Object.hasOwn(MODELS, model) ? MODELS[model] : undefined;
  if (!spec) return { ok: false, errors: [`unknown model ${model}`] };
  const errors = [];
  if (!value || typeof value !== 'object' || Array.isArray(value)) return { ok: false, errors: ['expected an object'] };
  for (const key of Object.keys(value)) if (!Object.hasOwn(spec.fields, key)) errors.push(`unexpected field ${key}`);
  for (const [name, f] of Object.entries(spec.fields)) {
    const v = Object.hasOwn(value, name) ? value[name] : undefined;
    if (v === undefined || v === null) { if (!f.nullable) errors.push(`missing required field ${name}`); continue; }
    if (f.array) { if (!Array.isArray(v)) { errors.push(`${name} must be an array`); continue; } v.forEach((item, i) => { if (!f.check(item)) errors.push(`${name}[${i}] is invalid`); }); }
    else if (!f.check(v)) errors.push(`${name} is invalid`);
  }
  return errors.length ? { ok: false, errors } : { ok: true, value };
}

